  quests: [
    { id: "johnfrost", cat: "gor", area: "arnhem", title: "Stand at the John Frostbrug",
      desc: "In September 1944, British paratroopers held the north end of this bridge over the Rhine for days; this is the bridge from the film 'A Bridge Too Far'. Today's bridge carries the name of John Frost, the officer who led the defence.",
      tip: "The Airborne at the Bridge info centre on the quay is free and looks straight at the bridge.", q: "Airborne at the Bridge Arnhem", tags: ["free"] },
    { id: "museumarnhem", cat: "gor", area: "arnhem", title: "Look at the Rhine from Museum Arnhem's garden",
      desc: "The museum sits on the edge of an ice-age ridge, and its new wing juts out over the slope into thin air. From the sculpture garden, the river and the Betuwe plain lie at your feet.",
      tip: "You don't need a ticket for the garden; inside, check out the Dutch magical realism collection.", q: "Museum Arnhem Utrechtseweg", tags: ["rainy day"] },
    { id: "waterval", cat: "gor", area: "sonsbeek", title: "Walk behind the Sonsbeek waterfall",
      desc: "Sonsbeek park, right in the middle of Arnhem, is hillier than you'd ever expect from flat Holland. Through the rock passage behind the big waterfall you can look out through the water itself.",
      tip: "After the waterfall, climb the slope and look over the park from the terrace of the white villa on top.", q: "Grote Waterval Park Sonsbeek Arnhem", tags: ["free"] },
    { id: "burgers", cat: "gor", area: "sonsbeek", title: "Enter the rainforest at Burgers' Bush",
      desc: "Bush, the giant indoor tropical hall of Burgers' Zoo, was one of the first and is one of the biggest of its kind in Europe. Birds and bats fly freely over your head; desert and ocean sections sit right next to it.",
      tip: "Go on a cold winter day: it's warm and humid inside, so dress in layers. A tunnel leads from the Bush to the desert.", q: "Koninklijke Burgers' Zoo Arnhem", tags: ["rainy day"] },
    { id: "valkhof", cat: "gor", area: "nijmegen", title: "Step into the thousand-year-old chapel at the Valkhof",
      desc: "This hill is the heart of Nijmegen, the oldest city in the Netherlands: the Romans were here, and so was Charlemagne. The octagonal Sint-Nicolaaskapel is among the oldest surviving buildings in the country; next to it stands the apse left from Barbarossa's palace.",
      tip: "From the wall at the north end of the park, look out over the Waal and the bridge; the chapel is open on certain days in season.", q: "Sint-Nicolaaskapel Valkhof Nijmegen", tags: ["free"] },
    { id: "kmm", cat: "gor", area: "cevre", title: "See the Van Goghs at Kröller-Müller",
      desc: "The museum in the middle of the woods holds the world's second-largest Van Gogh collection. One of Europe's biggest sculpture gardens also spreads out among the trees behind the building.",
      tip: "To get to the museum you first have to enter De Hoge Veluwe park; buy the tickets together and in advance.", q: "Kröller-Müller Museum Otterlo", tags: ["rainy day"] },
    { id: "hetloo", cat: "gor", area: "cevre", title: "Stroll the gardens of Paleis Het Loo",
      desc: "The palace in Apeldoorn was the summer home of the House of Orange for three centuries. Its symmetrical baroque gardens were rebuilt to the original plan; after a major renovation it reopened with a new wing buried underground.",
      tip: "Go up to the palace roof: you can only see the garden's pattern from above.", q: "Paleis Het Loo Apeldoorn" },
    { id: "hartenstein", cat: "gor", area: "cevre", title: "Tour Hartenstein in Oosterbeek",
      desc: "The villa that served as the British headquarters in the Battle of Arnhem is now the Airborne Museum. The basement relives the days of the siege with sound and light.",
      tip: "Walk over to the nearby Airborne cemetery too. Every September there are memorial ceremonies and the big Airborne march.", q: "Airborne Museum Hartenstein Oosterbeek", tags: ["rainy day"] },
    { id: "korenmarkt", cat: "ye", area: "arnhem", title: "Spend an evening on the Korenmarkt",
      desc: "The old grain market square is the centre of Arnhem's nightlife: bars and terraces on all four sides. Students and retirees alike head here in the evening.",
      tip: "On a sunny day the terraces fill up early; peek into the craft beer cafés on the side streets too.", q: "Korenmarkt Arnhem", kind: "snack" },
    { id: "hemel", cat: "ye", area: "nijmegen", title: "Have a beer in the monastery courtyard at De Hemel",
      desc: "Stadsbrouwerij De Hemel (Heaven) brews beer in the medieval Commanderie van Sint-Jan. Under the same roof they also make vinegar, mustard and spirits.",
      tip: "Start with a tasting board; in summer, sit in the inner courtyard.", q: "Stadsbrouwerij De Hemel Nijmegen", kind: "drink", tags: ["rainy day"] },
    { id: "blaauwehand", cat: "ye", area: "nijmegen", title: "Drop by In de Blaauwe Hand",
      desc: "Open since the 16th century, this little café is the oldest in Nijmegen. It takes its name from the dyers working next door, whose hands turned indigo blue from dyeing cloth.",
      tip: "It's right behind the Grote Markt, next to the church passage; the inside is tiny, so go early.", q: "In de Blaauwe Hand Nijmegen", kind: "meal", tags: ["rainy day"] },
    { id: "oortjeshekken", cat: "ye", area: "waal", title: "Take a break on the dyke in the Ooijpolder",
      desc: "Where Nijmegen ends, the Ooijpolder begins: floodplains, semi-wild horses and winding dykes. Oortjeshekken, up on the dyke, is the classic stop for walkers and cyclists.",
      tip: "Leave the city over the Ooypoort pedestrian bridge and walk or pedal along the dyke; on the way back the sun sets over the Waal.", q: "Oortjeshekken Ooij", kind: "meal" },
    { id: "mosterd", cat: "ye", area: "cevre", title: "Buy Doesburg mustard at the source",
      desc: "Doesburg, the Hanseatic town on the IJssel, is known for its mustard. The old mustard factory is now a museum that still produces with its stone mills and wooden barrels.",
      tip: "Buy fresh mustard from the counter; it's coarse-grained and sharp, nothing like supermarket mustard.", q: "Doesburgsche Mosterdfabriek Doesburg", kind: "meal", tags: ["rainy day"] },
    { id: "waag", cat: "ye", area: "cevre", title: "Slurp mustard soup at De Waag",
      desc: "Doesburg's Gothic weigh house with its stepped gables dates from the 15th century and counts as one of the oldest restaurants in the country. It's the right address for the local mustard soup.",
      tip: "Look at the old scales inside; then walk the town's main street all the way to the IJssel.", q: "Stadsbierhuys De Waag Doesburg", kind: "meal" },
    { id: "eusebius", cat: "dene", area: "arnhem", title: "Step onto the glass balcony of the Eusebiuskerk",
      desc: "The church tower, destroyed in the Battle of Arnhem, was rebuilt after the war. Take the lift to the top and you step onto balconies that jut out past the tower, with glass floors.",
      tip: "Dare to look down: the square is right beneath you. In clear weather you can see the Rhine and the John Frost bridge.", q: "Eusebiuskerk Arnhem" },
    { id: "trolley", cat: "dene", area: "arnhem", title: "Ride the trolleybus",
      desc: "Arnhem is the only city in the Netherlands with trolleybuses: silent buses hooked to overhead wires that have stood in for trams since the war. Even if you ride one every day, ride it once knowing it's special.",
      tip: "It leaves from Arnhem Centraal. Before you board, look at the giant curving concrete column inside the station.", q: "Arnhem Centraal" },
    { id: "openlucht", cat: "dene", area: "sonsbeek", title: "Ride the old tram at the Openluchtmuseum",
      desc: "Farms, mills and workshops dismantled from all over the country were rebuilt in the woods. Old trams run between them; the last few centuries of Dutch life in a single walk.",
      tip: "Set aside a full day. The smell of fresh bread from the bakery and poffertjes at the stall will find you.", q: "Nederlands Openluchtmuseum Arnhem" },
    { id: "vierdaagse", cat: "dene", area: "nijmegen", title: "Cheer on the walkers at the Vierdaagse",
      desc: "Every July tens of thousands of people walk around Nijmegen four days in a row: the world's largest multi-day walking event. On the last day St. Annastraat becomes the 'Via Gladiola' and finishers get gladioli.",
      tip: "Even if you don't walk, the Vierdaagsefeesten concerts in the city that week are free. Grab a spot for the Via Gladiola from the morning.", q: "St. Annastraat Nijmegen", months: [7], tags: ["free"] },
    { id: "oversteek", cat: "dene", area: "waal", title: "Join the Sunset March",
      desc: "De Oversteek bridge was built in memory of the 48 American soldiers who died crossing the Waal in small boats in 1944. At sunset, 48 pairs of lamps light up in sequence at marching pace, and every evening a veteran walks the bridge together with the lights.",
      tip: "The time shifts daily with sunset; anyone is welcome to walk quietly behind the veteran.", q: "De Oversteek Nijmegen", tags: ["free"] },
    { id: "spiegelwaal", cat: "dene", area: "waal", title: "Spend a summer day on the Spiegelwaal",
      desc: "To protect Nijmegen from floods, a second channel was dug beside the Waal, creating the island of Veur-Lent in between. The water of the side arm Spiegelwaal is calm, and its beaches are the city's summer seaside.",
      tip: "Cross the bridge from the centre onto the island, then get in the water from the Lentloper footbridge. The evening sun sets behind the city skyline.", q: "Spiegelwaal Nijmegen", months: [5, 6, 7, 8, 9], tags: ["free"] },
    { id: "hogeveluwe", cat: "dene", area: "cevre", title: "Cycle the Hoge Veluwe on a white bike",
      desc: "Hundreds of free white bikes wait at the national park's entrances: grab one and ride through heathland, sand dunes and pine forest. With luck you'll spot deer and wild mouflon.",
      tip: "In autumn come near sunset for the deer rutting season. Pedal all the way to the Jachthuis Sint Hubertus in the north.", q: "Bezoekerscentrum De Hoge Veluwe" },
    { id: "posbank", cat: "dene", area: "cevre", title: "Walk the purple heath at the Posbank",
      desc: "The hills of the Veluwezoom turn purple with heather blooming in late August. In a flat country: hills rolling to the horizon, with Scottish Highland cattle grazing among them.",
      tip: "On bloom-season weekends the roads clog up: come at sunrise or walk up from Rheden.", q: "Posbank Rheden", months: [8, 9], tags: ["free"] },
    { id: "sabelspoort", cat: "gor", area: "arnhem", title: "Pass under the Sabelspoort",
      desc: "Arnhem once had four medieval city gates; the Sabelspoort is the only one still standing. Its baroque front dates from 1642 and it sits right by the Rhine, a short walk from the bridge.",
      tip: "Combine it with the John Frost bridge and the river quay; the gate looks best from the Rijnkade side.", q: "Sabelspoort Arnhem", tags: ["free"], src: ["https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "kelders", cat: "dene", area: "arnhem", title: "Go down into Arnhem's medieval cellars",
      desc: "Under the shopping streets near the Rhine lies a network of around three dozen vaulted cellars where merchants once stored their goods. A walk through them shows the city that existed long before the war rebuilt its surface.",
      tip: "The entrance is on Oude Oeverstraat; the route stays cool all year, so bring a layer even in summer.", q: "Historische Kelders Arnhem", tags: ["rainy day"], src: ["https://en.wikivoyage.org/wiki/Arnhem", "https://exploringthenetherlands.com/things-to-do-in-arnhem/"] },
    { id: "taphuys", cat: "ye", area: "arnhem", title: "Drink a beer in the old post office",
      desc: "The grand neo-Gothic post office on Jansplein now pours beer and wine instead of stamping letters. 't Taphuys keeps the high ceilings and big windows of the old counter hall.",
      tip: "Pick something from the long draft list and look up: the building's original details are the real show.", q: "'t Taphuys Arnhem Jansplein", kind: "drink", tags: ["rainy day"], src: ["https://en.wikivoyage.org/wiki/Arnhem", "https://aliciavalenski.substack.com/p/what-to-eat-drink-see-and-do-in-arnhem"] },
    { id: "localsarnhem", cat: "ye", area: "arnhem", title: "Eat hyper-local at LOCALS",
      desc: "The restaurant in Hotel Haarhuis next to the station cooks with produce from the region and grows part of it in its own vertical farm. It is Arnhem's showcase for Gelderland flavours.",
      tip: "Finish with a drink at BLOU, the rooftop bar of the same hotel, for a view over the city.", q: "LOCALS Hotel Haarhuis Arnhem", kind: "meal", src: ["https://aliciavalenski.substack.com/p/what-to-eat-drink-see-and-do-in-arnhem"] },
    { id: "molenplaats", cat: "ye", area: "sonsbeek", title: "Visit the white water mill in Sonsbeek",
      desc: "At the edge of Sonsbeek park stands De Witte Watermolen, a historic water mill now part of Natuurcentrum Arnhem. The Molenschuur next to it serves local and organic food and drinks.",
      tip: "Have a drink at the Molenschuur by the mill pond, then walk up into the park towards the Belvédère.", q: "De Witte Watermolen Sonsbeek Arnhem", kind: "meal", src: ["https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "watermuseum", cat: "dene", area: "sonsbeek", title: "Play with water at the Watermuseum",
      desc: "In a country that lives below sea level, this hands-on museum in Sonsbeek explains where water comes from and where it goes, sewers included. Lots of buttons, pumps and splashing.",
      tip: "Locals like the lawns outside for a picnic afterwards; it sits right next to the Sonsbeek water mill.", q: "Nederlands Watermuseum Arnhem", tags: ["rainy day"], src: ["https://en.wikivoyage.org/wiki/Arnhem", "https://aliciavalenski.substack.com/p/what-to-eat-drink-see-and-do-in-arnhem"] },
    { id: "zypendaal", cat: "gor", area: "sonsbeek", title: "Peek inside Huis Zypendaal",
      desc: "Next door to busy Sonsbeek, Park Zypendaal is the quieter sibling, with ponds and an 18th-century country house whose ground floor you can visit. The park counts ten national monuments.",
      tip: "Walk from Sonsbeek over the Zijpendaalseweg; the house is at its best seen across the pond in front.", q: "Huis Zypendaal Arnhem", tags: ["free"], src: ["https://exploringthenetherlands.com/things-to-do-in-arnhem/", "https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "bastei", cat: "gor", area: "nijmegen", title: "Touch the Roman wall inside De Bastei",
      desc: "Roman Nijmegen, Noviomagus, lies mostly buried, but in De Bastei you walk past a Roman gate and wall and climb into the 16th-century Stratemakerstoren. The same building holds a natural history show about the region's landscape.",
      tip: "It sits below the Valkhof hill on the river side, so pair it with the Valkhof park and the Waalkade.", q: "De Bastei Nijmegen", tags: ["rainy day"], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/"] },
    { id: "kruittoren", cat: "gor", area: "nijmegen", title: "Find the Kruittoren in Kronenburgerpark",
      desc: "This park on the old city edge hides the 1425 Kruittoren (powder tower) and surviving stretches of the medieval wall between its ponds and lawns.",
      tip: "Bring a picnic; locals use the park as their back garden on sunny afternoons.", q: "Kruittoren Kronenburgerpark Nijmegen", tags: ["free"], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/"] },
    { id: "stevenstoren", cat: "dene", area: "nijmegen", title: "Climb the Stevenskerk tower",
      desc: "The Gothic Stevenskerk dominates the old town, and on selected days in the warm season you can climb its tower for a view over the Waal and the rooftops. Inside lies the tomb of Catherine of Bourbon.",
      tip: "Enter the church square through the Kerkboog, the archway from the Grote Markt; the church itself is free.", q: "Stevenskerk Nijmegen", months: [4, 5, 6, 7, 8, 9], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/", "https://en.wikivoyage.org/wiki/Nijmegen"] },
    { id: "deplak", cat: "ye", area: "nijmegen", title: "Order kaasgehakt at De Plak",
      desc: "Eetcafé De Plak on Bloemerstraat is an institution of Nijmegen's alternative scene, famous for its kaasgehakt, a cheese-filled meatball.",
      tip: "It is popular with students and fills up fast in the evening; come early or be ready to wait at the bar.", q: "Eetcafé De Plak Nijmegen", kind: "snack", src: ["https://en.wikivoyage.org/wiki/Nijmegen"] },
    { id: "muzieum", cat: "dene", area: "nijmegen", title: "Explore the dark at muZIEum",
      desc: "This museum lets you experience the world as blind and visually impaired people do, guided through a pitch-dark expedition by someone who knows it best.",
      tip: "Book ahead; there is also an augmented-reality walk through town that starts here.", q: "muZIEum Nijmegen", tags: ["rainy day"], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/"] },
    { id: "pannenkoekenboot", cat: "ye", area: "waal", title: "Eat pancakes on the Waal",
      desc: "The Pannenkoekenboot sails out from the Waalkade for a cruise with as many Dutch pancakes as you can manage, while the bridges and the skyline slide by.",
      tip: "Book in advance, especially at weekends; sit by a window on the river side.", q: "Pannenkoekenboot Nijmegen Waalkade", kind: "sweet", src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/"] },
    { id: "velorama", cat: "dene", area: "waal", title: "Ride back in time at Velorama",
      desc: "The national bicycle museum on the Waalkade shows how the Dutch fell for the bike, from wooden balance bikes to towering high-wheelers.",
      tip: "Afterwards walk the Waalkade terraces east towards the Valkhof for the river view.", q: "Velorama Nijmegen", tags: ["rainy day"], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/", "https://en.wikivoyage.org/wiki/Nijmegen"] },
    { id: "faceofnijmegen", cat: "gor", area: "waal", title: "Meet the Face of Nijmegen",
      desc: "On the river island Veur-Lent a giant metal face stares back at the city. The sculpture by Andreas Hetfeld is inspired by a Roman cavalry mask found in Nijmegen.",
      tip: "Cross the Snelbinder bike and foot bridge beside the railway bridge; the view back to the old town is the best skyline shot in the city.", q: "Face of Nijmegen Veur-Lent", tags: ["free"], src: ["https://exploringthenetherlands.com/things-to-do-in-nijmegen/"] },
    { id: "hoteldewereld", cat: "gor", area: "cevre", title: "Stand where the war ended in Wageningen",
      desc: "At Hotel de Wereld in Wageningen the German commander in the Netherlands capitulated to the Canadians on 5 May 1945; the papers were signed next door the following day because there was no typewriter.",
      tip: "Come on 5 May, when the town's Liberation Day celebrations centre on this square. Wageningen is a short bus ride from Ede-Wageningen station.", q: "Hotel de Wereld Wageningen", tags: ["free"], src: ["https://en.wikipedia.org/wiki/Hotel_de_Wereld", "https://en.wikivoyage.org/wiki/Wageningen"] },
    { id: "stadsbrouwerijwag", cat: "ye", area: "cevre", title: "Taste student-town beer in Wageningen",
      desc: "Wageningen's university crowd keeps a lively bar scene; the Stadsbrouwerij brews its own beer in a lane right off the market square.",
      tip: "Then try the beer list at De Vlaamsche Reus on the main square, which counts well over a hundred bottles.", q: "Stadsbrouwerij Wageningen", kind: "drink", src: ["https://en.wikivoyage.org/wiki/Wageningen"] },
    { id: "doorwerth", cat: "gor", area: "cevre", title: "Visit Kasteel Doorwerth on the Rhine",
      desc: "This moated castle in the Rhine floodplain west of Arnhem was badly damaged in 1944 and restored over decades. Today it holds furnished historic rooms and museums on hunting and nature.",
      tip: "Look for the huge black locust tree by the entrance, said to be the oldest in the country; the riverside walk to Oosterbeek starts nearby.", q: "Kasteel Doorwerth", src: ["https://nl.wikipedia.org/wiki/Kasteel_Doorwerth", "https://en.wikivoyage.org/wiki/Veluwe"] },
    { id: "plankenwambuis", cat: "ye", area: "cevre", title: "Eat Veluwe game at Planken Wambuis",
      desc: "A forest inn from 1926 between Ede and Arnhem, with a hunting-lodge interior and a menu built around venison and other Veluwe game.",
      tip: "Walk or cycle the Ginkelse Heide or the Planken Wambuis woods first; autumn is the high season for game.", q: "Planken Wambuis Ede", kind: "meal", src: ["https://www.plankenwambuis.nl/", "https://en.wikivoyage.org/wiki/Veluwe"] },
    { id: "museonder", cat: "dene", area: "cevre", title: "Go underground at Museonder",
      desc: "In the heart of De Hoge Veluwe park, Museonder shows what happens beneath the forest floor. The roots of a 135-year-old tree hang over your head in the middle of the hall.",
      tip: "It is part of the visitor centre, where you can also pick up a white bike; entry is included with the park ticket.", q: "Museonder Hoge Veluwe Otterlo", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Museonder", "https://en.wikivoyage.org/wiki/Veluwe"] },
    { id: "buren", cat: "gor", area: "cevre", title: "Find William and Anna in Buren",
      desc: "In the tiny fortified town of Buren, William of Orange married Anna van Buren in the Sint-Lambertuskerk in 1551, which is why the royal family still carries the title of count of Buren. A statue of the couple stands by the church.",
      tip: "Visit Museum Buren & Oranje in the old town hall and the Prins van Oranje mill on the ramparts; in spring the orchards around town bloom.", q: "Sint-Lambertuskerk Buren", src: ["https://nl.wikipedia.org/wiki/Buren_(stad)"] },
    { id: "bronkhorst", cat: "gor", area: "cevre", title: "Stroll through tiny Bronkhorst",
      desc: "With barely a hundred or so residents, Bronkhorst on the IJssel ranks among the smallest towns with city rights in the country. Its cobbled lanes, castle mound and little chapel make a perfect short walk.",
      tip: "Climb the castle hill, the only trace left of the medieval castle, then look out over the IJssel floodplains.", q: "Bronkhorst Bronckhorst", tags: ["free"], src: ["https://en.wikipedia.org/wiki/Bronkhorst", "https://en.wikivoyage.org/wiki/Achterhoek"] },
    { id: "huisbergh", cat: "gor", area: "cevre", title: "Tour Kasteel Huis Bergh in 's-Heerenberg",
      desc: "This moated castle in the Achterhoek holds the largest private collection of early Italian art in the Netherlands, along with manuscripts, ivory and portraits of the counts of Bergh.",
      tip: "Stroll the castle garden, restored to its 1727 layout; you can even sleep in one of the towers.", q: "Kasteel Huis Bergh 's-Heerenberg", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Kasteel_Huis_Bergh", "https://en.wikivoyage.org/wiki/Achterhoek"] },
    { id: "willibrordabdij", cat: "dene", area: "cevre", title: "Listen to the monks at Sint Willibrordsabdij",
      desc: "In the Slangenburg woods just outside Doetinchem, Benedictine monks keep the hours of prayer. The chapel is open all day and anyone can quietly join a service.",
      tip: "Combine it with a walk past nearby Kasteel de Slangenburg; the abbey is a short bike ride from Doetinchem station.", q: "Sint Willibrordsabdij Doetinchem", tags: ["free"], src: ["https://en.wikivoyage.org/wiki/Doetinchem"] },
    { id: "walterbier", cat: "ye", area: "cevre", title: "Taste Walterbier in Doetinchem",
      desc: "The Stadsbrouwerij Doetinchem brews Walterbier right in the centre of the Achterhoek's main town, and opens up for brewery tours.",
      tip: "Monthly public tours run on a Sunday afternoon; otherwise just drop in for a glass in the old centre.", q: "Stadsbrouwerij Doetinchem Grutstraat", kind: "drink", src: ["https://en.wikivoyage.org/wiki/Doetinchem"] },
    { id: "jachthut", cat: "ye", area: "cevre", title: "Eat pancakes at the Jachthut op den Hamert",
      desc: "A pancake restaurant in a hunting lodge on the edge of the river dunes of De Hamert, near Wellerlooi in Noord-Limburg. It is the classic start and finish of walks through the Maasduinen.",
      tip: "Earn your pancake first: do one of the marked dune loops that begin right outside, then sit down with muddy boots.", q: "Jachthut op den Hamert Wellerlooi", kind: "sweet", src: ["https://www.anwb.nl/wandelen/routes/parel-aan-de-maas"] },
    { id: "hamert", cat: "dene", area: "cevre", title: "Walk the river dunes of De Hamert",
      desc: "National Park De Maasduinen holds the longest belt of river dunes in the Netherlands. At Landgoed De Hamert, trails cross drifting sand, heath and fens, past a Bronze Age burial mound.",
      tip: "Marked loops of different lengths start from the information board at the Jachthut; bus 83 between Venlo and Nijmegen stops at Wellerlooi.", q: "Landgoed De Hamert Wellerlooi", tags: ["free"], src: ["https://www.anwb.nl/wandelen/routes/parel-aan-de-maas", "https://nl.wikipedia.org/wiki/Nationaal_Park_De_Maasduinen"] },
    { id: "grebbeberg", cat: "gor", area: "cevre", title: "Pay respects at the Grebbeberg war cemetery",
      desc: "On the hill above Rhenen lie some 800 soldiers who fell in May 1940 defending the Grebbe line against the German invasion, many on the very spot where they fought.",
      tip: "Walk on through the woods of the Grebbeberg for views over the Rhine floodplain.", q: "Militair Ereveld Grebbeberg Rhenen", tags: ["free"], src: ["https://en.wikivoyage.org/wiki/Rhenen"] },
    { id: "cunerakerk", cat: "dene", area: "cevre", title: "Climb the Cunera tower in Rhenen",
      desc: "The late Gothic Cunerakerk tower rises high above the Rhine town of Rhenen and the river landscape, with the Grebbeberg on one side and the Betuwe on the other.",
      tip: "Buy tower tickets at the tourist office; the church itself is free to look into.", q: "Cunerakerk Rhenen", src: ["https://en.wikivoyage.org/wiki/Rhenen"] },
    { id: "zutphen", cat: "gor", area: "cevre", title: "The chained library in Zutphen",
      desc: "In the 16th-century Librije inside the Walburgiskerk, the books are still chained to the reading desks. One of the few chained libraries in Europe to survive in its original state.",
      tip: "The Librije can only be visited with a guide or at set hours; check before you go.", q: "Librije Walburgiskerk Zutphen", tags: ["rainy day"] },
    { id: "pelikaan", cat: "ye", area: "cevre", title: "Sip coffee at De Pelikaan in Zutphen",
      desc: "De Pelikaan has been roasting coffee and selling tea since 1816 and is a royal warrant holder. Its old-fashioned shop has a small schenkerij where you drink the house blends with something sweet.",
      tip: "Take a bag of a house blend home; Zutphen is about 45 minutes from Zwolle by train along the IJssel.", q: "De Pelikaan Pelikaanstraat Zutphen", kind: "coffee", src: ["https://www.de-pelikaan.nl/", "https://www.dutchnews.nl/2025/01/dutch-destinations-go-medieval-in-the-city-of-towers/"] },
    { id: "zutphenhofjes", cat: "dene", area: "cevre", title: "Go hofje hunting in Zutphen",
      desc: "Behind Zutphen's street fronts hide almshouse courtyards built for the elderly, poor and widowed, the oldest being the Oude Bornhof from 1320. Ruitershofje, Agnietenhof and Luthers Hofje are other finds.",
      tip: "Courtyards are lived in: go quietly, and finish with the Martinetsingel walk along the old walls.", q: "Oude Bornhof Zutphen", tags: ["free"], src: ["https://www.dutchnews.nl/2025/01/dutch-destinations-go-medieval-in-the-city-of-towers/"] },
    { id: "maashorst", cat: "dene", area: "cevre", title: "Look for wisent in De Maashorst",
      desc: "De Maashorst is a big landscape park of heath, forest and sand between Oss and Uden. Since 2016 European bison (wisent) and Exmoor ponies roam part of it freely.",
      tip: "Start at the visitor centre in Slabroek near Nistelrode, where most walking routes begin, and keep a respectful distance from the animals.", q: "Bezoekerscentrum De Maashorst Erenakkerstraat 5 Nistelrode", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Maashorst_(natuurgebied)", "https://en.wikivoyage.org/wiki/%27s-Hertogenbosch"] },
    { id: "duivelshuis", cat: "gor", area: "arnhem", title: "Spot the satyrs on the Duivelshuis",
      desc: "This 16th-century town castle on Koningstraat is known as the Devil's House because of the satyr figures on its facade. It was the home of the warlord Maarten van Rossum and today holds the office of Arnhem's mayor.",
      tip: "Look closely at the carved figures on the front; the house is a two-minute walk from the Eusebiuskerk and the Walburgiskerk.", q: "Duivelshuis, Koningstraat, Arnhem", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Duivelshuis_(Arnhem)", "https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "walburgiskerk", cat: "gor", area: "arnhem", title: "Find Arnhem's oldest church, the Walburgiskerk",
      desc: "The Sint-Walburgiskerk, with its distinctive pair of towers on the west front, is the oldest church building still standing in Arnhem. It was built on the grounds of the old count's court, once the residence of Count Reinald I of Guelders, and today hosts exhibitions and concerts rather than services.",
      tip: "Check what is on before you go, as the doors are mostly open for events; the twin towers look best from Sint Walburgisplein.", q: "Sint-Walburgiskerk, Sint Walburgisplein, Arnhem", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Sint-Walburgiskerk_(Arnhem)", "https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "moortgat", cat: "ye", area: "arnhem", title: "Settle into the brown café 't Moortgat",
      desc: "Café 't Moortgat on Ruiterstraat is a small, old-fashioned brown café that beer lovers have relied on for years. It pours around a dozen draught beers and keeps a long list of bottles, much of it Belgian and craft.",
      tip: "Ask the bar for a tip from the bottle list; it is just a few steps from Jansplein, so it pairs well with a drink at 't Taphuys.", q: "Café 't Moortgat, Ruiterstraat 35, Arnhem", kind: "meal", src: ["https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "focusfilm", cat: "dene", area: "arnhem", title: "Catch an art-house film at Focus",
      desc: "Focus Filmtheater is Arnhem's film house, showing a wider and more adventurous programme than the multiplexes. It stands on Audrey Hepburnplein, the square named after the actress who spent her teenage war years in Arnhem.",
      tip: "Films in other languages run with Dutch subtitles, so pick English-language titles; the Korenmarkt bars are around the corner for afterwards.", q: "Focus Filmtheater Arnhem, Audrey Hepburnplein", tags: ["rainy day"], src: ["https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "meinerswijk", cat: "dene", area: "arnhem", title: "Cross the Rhine to the Meinerswijk floodplains",
      desc: "Right across the river from the old centre, Stadsblokken-Meinerswijk is a wide floodplain of meadows and ponds where locals walk, cycle and picnic. People have lived here since Roman times, and the little hamlet of De Praets still sits in the middle.",
      tip: "Walk over the Nelson Mandelabrug and turn west along the dyke; the view back to the Eusebius tower and the John Frost bridge is the classic Arnhem skyline.", q: "Stadsblokken-Meinerswijk, Arnhem", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Stadsblokken-Meinerswijk", "https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "belvedere", cat: "gor", area: "sonsbeek", title: "Climb the Belvédère tower in Sonsbeek",
      desc: "Baron Van Heeckeren, then owner of Sonsbeek, built this lookout tower on the Ruyterenberg between 1824 and 1826. Because it stands on one of the highest points in the park, its top reaches about as high as the Eusebiuskerk tower, with views over the city and far beyond.",
      tip: "The tower opens on a limited schedule, mostly on Sunday afternoons with a tower guide; ask at the park visitor centre by the Witte Watermolen, and peek into the old ice cellar nearby too.", q: "Belvédère, Park Sonsbeek, Arnhem", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Belv%C3%A9d%C3%A8re_(Arnhem)"] },
    { id: "molendekroon", cat: "gor", area: "sonsbeek", title: "Find the windmill in the middle of Klarendal",
      desc: "Molen De Kroon is the pride of the working-class Klarendal district: a windmill that was moved here from the Amsterdamseweg in 1870 and still works today. It rises among the rowhouses, a surprising sight just north-east of the centre.",
      tip: "Volunteers run the mill on set days, when you can usually go inside. Combine it with the fashion shops lower down the Klarendalseweg.", q: "Molen De Kroon, Klarendal, Arnhem", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Klarendal", "https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "modekwartier", cat: "dene", area: "sonsbeek", title: "Shop young designers in the Modekwartier",
      desc: "Arnhem is home to the ArtEZ art school, whose fashion alumni include Viktor & Rolf. Since 2008 the lower Klarendalseweg has been the Modekwartier, where run-down shopfronts became studios and boutiques of designers who often sell straight from their own workroom.",
      tip: "Go on a Thursday to Saturday afternoon, when most ateliers are open; many makers are happy to talk about their work.", q: "Klarendalseweg, Arnhem", src: ["https://nl.wikipedia.org/wiki/Klarendal", "https://www.regioarnhem.com/nl/ontdek/mode-en-design"] },
    { id: "klarenbeek", cat: "dene", area: "sonsbeek", title: "Walk the steep woods of Park Klarenbeek",
      desc: "While Sonsbeek draws the crowds, neighbouring Park Klarenbeek is a quiet forested park with surprisingly steep slopes on the edge of the Veluwe ridge. Locals use it for running and dog walks, and the Klarenbeek open-air pool on Hommelseweg is a summer favourite.",
      tip: "The open-air pool opens roughly from April to August; on hot days come early in the morning.", q: "Park Klarenbeek, Arnhem", tags: ["free"], src: ["https://en.wikivoyage.org/wiki/Arnhem"] },
    { id: "valkhofmuseum", cat: "gor", area: "nijmegen", title: "See Roman Nijmegen at the renewed Valkhof Museum",
      desc: "The Valkhof Museum brings together the archaeology of the Roman frontier, cultural history and contemporary art, with a strong focus on the Limes, the Roman border that became UNESCO World Heritage in 2021. After a long renovation it reopened in June 2026 in its glass building on Kelfkensbos.",
      tip: "Pair it with the Valkhof park right behind it; the walk ends at the Belvédère tower in the Hunnerpark with a view over the Waal.", q: "Valkhof Museum, Kelfkensbos 59, Nijmegen", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Valkhof_Museum", "https://parametric-architecture.com/uns-renews-nijmegens-valkhof-museum/", "https://en.wikivoyage.org/wiki/Nijmegen"] },
    { id: "langehezelstraat", cat: "gor", area: "nijmegen", title: "Wander the Lange Hezelstraat",
      desc: "Lange Hezelstraat runs along the edge between the upper and lower town, lined with independent shops, cafés and old facades. Its eastern continuation is the Stikke Hezelstraat, where 'stikke' is local dialect for steep, a name that only became official in 1910.",
      tip: "Walk it from the Grote Markt side, then climb the Stikke Hezelstraat for a sense of how hilly the old city is.", q: "Lange Hezelstraat, Nijmegen", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Lange_Hezelstraat"] },
    { id: "waagh", cat: "ye", area: "nijmegen", title: "Have lunch in the old weigh house De Waagh",
      desc: "The Renaissance weigh house on the Grote Markt was built in 1612, when merchants had to have their goods weighed and pay tax on the weight. It survived wartime bombing, and since 1977 it has been a town café and restaurant.",
      tip: "Take a table on the terrace facing the market for people watching, then look up at the facade from across the square.", q: "De Waagh, Grote Markt 26, Nijmegen", kind: "meal", src: ["https://en.visitnijmegen.com/locations/359159036/de-waagh-stadscafe-en-restaurant", "https://en.visitnijmegen.com/to-see-do/food-drinks"] },
    { id: "daen", cat: "ye", area: "nijmegen", title: "Share a board of bites at Café Daen",
      desc: "Café Daen fills De Oude Laeckenhal, a monumental cloth hall built around 1600 on the Grote Markt. It is known for its craft beer list and the 'Daenplanken', boards of small dishes with meat, fish or vegetarian bites.",
      tip: "It is closed early in the week and opens Thursday to Sunday; the heated terrace works well into autumn.", q: "Café Daen, Grote Markt 23, Nijmegen", kind: "snack", src: ["https://en.visitnijmegen.com/locations/2626561210/cafe-daen", "https://en.visitnijmegen.com/to-see-do/food-drinks"] },
    { id: "doornroosje", cat: "dene", area: "nijmegen", title: "Catch a gig at Doornroosje",
      desc: "Doornroosje, Roosje to locals, is Nijmegen's big pop venue next to the station, with rock, electronic, hip hop and techno nights. Its smaller sister venue Merleyn on Hertogstraat books more intimate shows.",
      tip: "Check the programme a few weeks ahead, as popular shows sell out; the club nights run late at weekends.", q: "Doornroosje, Stationsplein 11, Nijmegen", tags: ["rainy day"], src: ["https://en.wikivoyage.org/wiki/Nijmegen"] },
    { id: "waalbrug", cat: "gor", area: "waal", title: "Walk across the Waalbrug",
      desc: "The great steel arch of the Waalbrug was begun in 1931 and opened five years later. In September 1944 it was captured intact during Operation Market Garden, and today it still carries traffic straight into the old town.",
      tip: "Walk it on the pavement for the best view of the Valkhof hill and the Waalkade; De Oversteek is two kilometres downstream if you want to loop back.", q: "Waalbrug, Nijmegen", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Waalbrug_Nijmegen"] },
    { id: "persingen", cat: "gor", area: "waal", title: "Visit Persingen, one of the smallest church villages",
      desc: "Persingen in the Ooijpolder has fewer than a hundred residents, yet keeps its own late-Gothic church, in a parish first mentioned in 1333. South of the church, a grassy mound marks where Huis Persingen stood until it burned in 1613 and its ruins washed away in floods.",
      tip: "The church is now used for exhibitions and weddings, so it is not always open; the polder roads around it are perfect for cycling.", q: "Persingen, Berg en Dal", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Persingen"] },
    { id: "thornschemolen", cat: "ye", area: "waal", title: "Eat pancakes from mill flour at the Thornsche Molen",
      desc: "The windmill near Persingen was destroyed in the Second World War and rebuilt in 2015; since 2016 it grinds flour again, which the restaurant at its foot uses for its pancakes. Inside is a small exhibition on the mill, the war along the border and floods in the Ooijpolder.",
      tip: "Sit on the terrace for the view over the hills of Beek and into Germany; it is an easy stop on a cycling loop through the polder.", q: "De Thornsche Molen, Thornsestraat 20, Persingen", kind: "sweet", src: ["https://en.visitnijmegen.com/locations/325759232/restaurant-de-thornsche-molen"] },
    { id: "duivelsberg", cat: "ye", area: "waal", title: "Eat pancakes in the woods at De Duivelsberg",
      desc: "In the forest of the Duivelsberg nature reserve, on the hills above the Ooijpolder, this old inn has served pancakes from the same family recipe for nearly fifty years. Checked tablecloths and antiques fill the dining room.",
      tip: "Several walks through the reserve start and end here; families can do the Roekoe-tocht trail with questions and small tasks.", q: "Pannenkoekenrestaurant De Duivelsberg, Berg en Dal", kind: "sweet", src: ["https://www.kidsproof.nl/nijmegen/uitje/pannenkoekenrestaurant-de-duivelsberg-de-duivelsberg", "https://en.visitnijmegen.com/to-see-do/food-drinks"] },
    { id: "millingerwaard", cat: "dene", area: "waal", title: "Walk the wild floodplain of the Millingerwaard",
      desc: "The Millingerwaard near Kekerdom is about 400 hectares of riverside wilderness on the Waal, part of the Gelderse Poort. Staatsbosbeheer lets nature take its course here, so you walk through marsh, scrub and floodplain forest, crossing a side channel on dams when the water is low.",
      tip: "Wear boots; after high water some paths and crossings are flooded, so check the river level before you go.", q: "Millingerwaard, Kekerdom", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Millingerwaard"] },
    { id: "fortpannerden", cat: "dene", area: "waal", title: "Explore Fort Pannerden where the Rhine splits",
      desc: "Built between 1869 and 1872, this fort guards the point where the Rhine divides into the Waal and the Pannerdens Kanaal. Squatters occupied it in 2000 and retook it after a 2006 eviction, then agreed to hand it over for restoration; it reopened to the public in 2016.",
      tip: "Guided tours run through the day and are included in the ticket, or take the audio tour; book ahead at busy times and check opening days, which are limited in winter.", q: "Fort Pannerden, Waaldijk 1, Doornenburg", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Fort_Pannerden", "https://www.fijnuit.nl/2505/fort-pannerden"] },
    { id: "doornenburg", cat: "gor", area: "cevre", title: "Cross the bridge into Kasteel Doornenburg",
      desc: "One of the largest and best-preserved castles in the country, Doornenburg has an outer bailey with a chapel and farm, linked to the main keep by a narrow wooden bridge. A British bombing raid wrecked it in March 1945 and rebuilding took until 1968; it starred as 'Oldenstein' in the 1968 TV series Floris.",
      tip: "Reserve tickets online; Fort Pannerden is a short bike ride away, so you can do both in one day.", q: "Kasteel Doornenburg", src: ["https://nl.wikipedia.org/wiki/Kasteel_Doornenburg", "https://www.kasteeldoornenburg.nl/"] },
    { id: "rosendael", cat: "gor", area: "cevre", title: "Dodge the trick fountains at Kasteel Rosendael",
      desc: "Rosendael in Rozendaal, first mentioned in 1314, has the largest tower of its kind in the Netherlands, with walls up to four metres thick. Its park is full of follies: shell galleries, a cascade, a tea pavilion and the Bedriegertjes, hidden fountains that soak unsuspecting visitors.",
      tip: "Guided castle tours run Tuesday to Saturday, and on Sunday afternoons you can walk the rooms yourself; the castle café is open most days.", q: "Kasteel Rosendael, Rozendaal", src: ["https://nl.wikipedia.org/wiki/Kasteel_Rosendael", "https://www.glk.nl/rosendael"] },
    { id: "vrijheidsmuseum", cat: "gor", area: "cevre", title: "Learn the border's war story at the Vrijheidsmuseum",
      desc: "In the hills outside Groesbeek, the Vrijheidsmuseum tells the story of the Second World War and the liberation of the Dutch-German border region in 1944 and 1945. Formerly the Nationaal Bevrijdingsmuseum, it moved into a new building in 2019 and also looks at freedom and unfreedom today.",
      tip: "Set aside at least half a day; the Canadian war cemetery outside Groesbeek is a short drive away.", q: "Vrijheidsmuseum, Wylerbaan 4, Groesbeek", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Vrijheidsmuseum"] },
    { id: "apenheul", cat: "dene", area: "cevre", title: "Meet free-roaming monkeys at Apenheul",
      desc: "Apenheul in the woods of Apeldoorn keeps more than 300 primates of over 30 species in natural-looking habitats with hardly any bars or fences. Several species roam freely among visitors, while gorillas, bonobos and orangutans live on islands surrounded by moats.",
      tip: "It is a seasonal park that closes in winter, so check the dates; arrive at opening time to see the apes at their most active.", q: "Apenheul, J.C. Wilslaan 21, Apeldoorn", src: ["https://nl.wikipedia.org/wiki/Apenheul", "https://en.wikivoyage.org/wiki/Apeldoorn"] },
    { id: "ginkelseheide", cat: "dene", area: "cevre", title: "Walk the Ginkelse Heide drop zone",
      desc: "On 17 September 1944 Allied paratroopers landed on this heath near Ede at the start of the Battle of Arnhem. Today a flock of about 160 sheep grazes among the heather and woods, and the landings are commemorated here every September.",
      tip: "Visit in late August or early September for the blooming heather; the sheepfold area is also where locals fly kites.", q: "Ginkelse Heide, Ede", months: [8, 9], tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Ginkelse_Heide"] },
    { id: "loenensewaterval", cat: "gor", area: "cevre", title: "See the biggest waterfall drop in the country at Loenen",
      desc: "Just outside Loenen on the edge of the Veluwe, the man-made Grote Waterval has the largest height difference of any waterfall in the Netherlands. It is a modest cascade by mountain standards, but a real surprise in a flat land.",
      tip: "Combine it with the smaller Kleine Waterval nearby and the Ereveld Loenen war cemetery, both a short walk or bike ride away.", q: "Loenense Waterval, Loenen", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Loenen_(Apeldoorn)", "https://en.wikivoyage.org/wiki/Apeldoorn"] },
    { id: "delocht", cat: "gor", area: "cevre", title: "Step into an old Limburg village at De Locht",
      desc: "Museumdorp De Locht in Melderslo, opened in 1990, recreates rural life in North Limburg between about 1850 and 1950. Separate pavilions tell the story of asparagus and mushroom growing and early greenhouses, and you can look into a smithy, a saddlery and a clog maker's workshop.",
      tip: "Have coffee with a slice of vlaai in Restaurant De Hoeve; the museum closes for a few weeks from mid-November when it turns into a Sinterklaas village.", q: "Museumdorp De Locht, Broekhuizerdijk 16d, Melderslo", tags: ["rainy day"], src: ["https://nl.wikipedia.org/wiki/Museum_De_Locht", "https://delocht.nl/"] },
    { id: "hackfort", cat: "dene", area: "cevre", title: "Walk the Hackfort estate near Vorden",
      desc: "Kasteel Hackfort, built in the 14th century and rebuilt after Spanish troops largely destroyed it in 1586, sits at the heart of a 735-hectare estate of woods, meadows and lanes. Natuurmonumenten became sole owner in 1981, and a historic watermill still stands beside the castle.",
      tip: "Vorden has more castles than any other Achterhoek village; use Hackfort as the start of a cycling loop past the others.", q: "Kasteel Hackfort, Baakseweg, Vorden", tags: ["free"], src: ["https://nl.wikipedia.org/wiki/Kasteel_Hackfort", "https://en.wikivoyage.org/wiki/Achterhoek"] },
    { id: "echoput", cat: "ye", area: "cevre", title: "Dine on Veluwe game at De Echoput",
      desc: "The Klosse family opened a tearoom in the royal forests near Apeldoorn in 1955, and it grew into one of the country's best-known game restaurants. Today it has a Grand Bistro and the Michelin-starred Wild Atelier, both built around game from the surrounding woods.",
      tip: "Book ahead, especially in the autumn game season; the historic echo well that gave the place its name is right next door.", q: "De Echoput, Amersfoortseweg 86, Hoog Soeren", kind: "meal", src: ["https://www.echoput.nl/", "https://en.wikivoyage.org/wiki/Apeldoorn"] },
    { id: "deplack", cat: "ye", area: "cevre", title: "Sip local wine at Wijngaard de Plack",
      desc: "At the foot of the Reichswald near Groesbeek, a family farm founded in 1845 turned to poultry in 1970 and planted vines in 2006. Its guest restaurant serves Dutch dishes looking out over the hilly countryside.",
      tip: "It is open Wednesday, Saturday and Sunday from late morning; Groesbeek has more vineyards on its slopes, so cycle between them.", q: "Wijngaard de Plack, Ketelstraat 36, Groesbeek", kind: "drink", src: ["https://en.visitnijmegen.com/locations/4156120877/wijngaard-de-plack"] },
    { id: "zwaantje", cat: "ye", area: "cevre", title: "Warm up by the fire at Herberg 't Zwaantje",
      desc: "This inn sits in the woods between Mook and Groesbeek, close to the heath of the Mookerheide. It has a café with an open fire, a terrace facing the trees and a kitchen with regional Dutch dishes.",
      tip: "Walk the Mookerheide first and come in for coffee or dinner; it is closed on Mondays.", q: "Herberg 't Zwaantje, Groesbeekseweg 106, Mook", kind: "meal", src: ["https://en.visitnijmegen.com/locations/3667900646/herberg-restaurant-t-zwaantje"] },
    { id: "beken", cat: "ye", area: "cevre", title: "Have an organic lunch at Boscafé de Beken",
      desc: "Tucked in the green near Renkum, Boscafé de Beken works with organic and fair-trade products, from coffee to bread. When the harvest allows, vegetables come from its own kitchen garden.",
      tip: "It makes a good stop on a walk through the brook valleys and estates around Renkum.", q: "Boscafé de Beken, Nieuwe Keijenbergseweg 174, Renkum", kind: "meal", src: ["https://www.regioarnhem.com/nl/veluwezoom/artikelen/boscafes"] },
    { id: "carolinahoeve", cat: "ye", area: "cevre", title: "Stop for cake at the Carolinahoeve",
      desc: "This farm from 1851 lies in the middle of Veluwezoom National Park, near the Onzalige Bossen and the Hagenau estate. Walkers, cyclists and riders drop in for coffee and cake, a toastie or a drink.",
      tip: "Reach it on foot or by bike from De Steeg; it sits on the quiet side of the park, away from the Posbank crowds.", q: "De Carolinahoeve, De Steeg", kind: "sweet", src: ["https://www.regioarnhem.com/nl/veluwezoom/artikelen/boscafes"] }
  ]
